from langflow.custom import Component
from langflow.io import DataInput, Output
from langflow.schema import Data
from langflow.schema.message import Message


class LegalQueryBuilder(Component):
    display_name = "Legal Query Builder"
    description = "Mengubah kategori & indikator paket berisiko tertinggi (Fase 1) menjadi kueri RAG regulasi."
    icon = "search"

    inputs = [
        DataInput(
            name="fraud_data",
            display_name="Fraud Data (JSON)",
            info=(
                "Hasil lengkap Fase 1 (punya 'top_package'/'packages') atau satu paket. "
                "Paket dengan severity tertinggi dipilih otomatis."
            ),
        ),
    ]

    outputs = [
        Output(display_name="Formatted Query", name="formatted_query", method="build_query"),
    ]

    def _default_query(self, reason: str) -> Message:
        query_text = "persekongkolan tender kartel pengadaan barang jasa pemerintah"
        self.status = f"{reason} — pakai query default: {query_text}"
        return Message(text=query_text)

    def build_query(self) -> Message:
        raw = self.fraud_data.data if isinstance(self.fraud_data, Data) else self.fraud_data
        if not raw or not isinstance(raw, dict) or raw.get("error"):
            return self._default_query("Input kosong/tidak valid")

        package = raw
        if "packages" in raw:
            packages = raw.get("packages") or []
            if not packages:
                return self._default_query("Tidak ada paket di dalam data")
            # v2: hasil sudah diurutkan (severity, indeks); top_package = paket teratas.
            package = raw.get("top_package") or packages[0]

        category = package.get("category", "")
        evidence = package.get("graph_evidence") or {}
        reasons = list(evidence.get("connected_reasons_id") or evidence.get("connected_reasons") or [])
        if (package.get("cobid_evidence") or {}).get("rotation_detected"):
            reasons.append("rotasi pemenang bergilir antar paket")
        if package.get("participant_count") == 1:
            reasons.append("tender hanya satu penawar")
        reasons_text = ", ".join(reasons) if reasons else "tidak ada bukti relasional signifikan"

        comps = package.get("component_scores", {})
        price_high = comps.get("variance_screen_score", 0) >= 50 or comps.get("margin_screen_score", 0) >= 50
        price_keywords = " mengatur harga penawaran mendekati HPS" if price_high else ""

        query_text = f"persekongkolan tender kartel {category}{price_keywords} dengan bukti {reasons_text}".strip()
        self.status = f"Query untuk paket {package.get('package_id', '-')}: {query_text}"
        return Message(text=query_text)

