import os
import sys
import tempfile

from langflow.custom import Component
from langflow.io import FileInput, StrInput, Output
from langflow.schema import Data


def _resolve_module_dir() -> str:
    """Folder tempat fraud_detection.py berada. Atur lewat environment variable
    SIDIK_TENDER_MODULE_DIR (disarankan). Fallback ke path lama jika ada."""
    env = os.environ.get("SIDIK_TENDER_MODULE_DIR")
    if env and os.path.isdir(env):
        return env
    legacy = "/home/frey/Documents/Hackathon Hacktiv8/RILL LPSE anti korupsi"
    return legacy if os.path.isdir(legacy) else os.getcwd()


class FraudPerceptionComponent(Component):
    display_name = "Fraud Perception Layer"
    description = "Fase 1 (deterministik): sinyal harga/waktu, graf relasi, co-bidding, override bukti keras"
    icon = "file-search"

    inputs = [
        FileInput(
            name="csv_file",
            display_name="Tender CSV File",
            file_types=["csv"],
            required=False,
            info="Upload manual langsung di kanvas Langflow",
        ),
        StrInput(
            name="raw_csv_content",
            display_name="Raw CSV Content / File Path",
            required=False,
            info="Isi teks mentah CSV dari Website, atau path file .csv dari IBM Bob",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(display_name="Fraud Scores + Graph", name="result", method="analyze"),
    ]

    def _safe_existing_csv(self, content: str):
        """Terima path hanya jika satu baris, berakhiran .csv, dan (bila diset) berada di
        folder yang diizinkan (SIDIK_TENDER_ALLOWED_DIR)."""
        if "\n" in content or not content.lower().endswith(".csv"):
            return None
        real = os.path.realpath(content)
        if not os.path.isfile(real):
            return None
        allowed = os.environ.get("SIDIK_TENDER_ALLOWED_DIR")
        if allowed and not real.startswith(os.path.realpath(allowed) + os.sep):
            return None
        return real

    def analyze(self) -> Data:
        module_dir = _resolve_module_dir()
        if module_dir not in sys.path:
            sys.path.insert(0, module_dir)
        from fraud_detection import run_fraud_analysis

        target_file, temp_path = None, None
        raw = (getattr(self, "raw_csv_content", None) or "").strip()

        if raw:
            target_file = self._safe_existing_csv(raw)
            if target_file is None:
                tmp = tempfile.NamedTemporaryFile(delete=False, suffix=".csv", mode="w", encoding="utf-8")
                tmp.write(raw)
                tmp.close()
                target_file = temp_path = tmp.name
        elif getattr(self, "csv_file", None):
            target_file = self.csv_file

        if not target_file:
            return Data(data={"error": "Data CSV belum dimasukkan."})

        try:
            return Data(data=run_fraud_analysis(target_file))
        except (KeyError, ValueError) as exc:
            return Data(data={"error": f"CSV tidak valid atau kolom wajib hilang: {exc}"})
        finally:
            if temp_path and os.path.exists(temp_path):
                os.remove(temp_path)

