def _as_text(value) -> str:
    return str(getattr(value, "text", value) or "")


class ReportAssembler(Component):
    display_name = "Report Assembler"
    description = (
        "Merakit laporan final: JSON deterministik dari Fase 1 + narasi LLM, "
        "dengan validasi pasal (harus ada di konteks RAG), angka, status, dan nama perusahaan."
    )
    icon = "file-text"

    inputs = [
        DataInput(
            name="fraud_data",
            display_name="Fraud Data (Fase 1)",
            info="Output lengkap Fraud Perception Layer (berisi report_json & top_package).",
        ),
        MessageTextInput(
            name="legal_output",
            display_name="Legal Narrative (LLM)",
            info="Keluaran LLM: blok ```json pemetaan_regulasi + narasi Markdown.",
        ),
        MessageTextInput(
            name="regulation_context",
            display_name="Regulation Context (RAG)",
            info="Kutipan regulasi hasil retrieval; dipakai untuk memverifikasi pasal yang dikutip LLM.",
        ),
    ]

    outputs = [
        Output(display_name="Final Report", name="final_report", method="build_report"),
    ]

    def build_report(self) -> Message:
        module_dir = _resolve_module_dir()
        if module_dir not in sys.path:
            sys.path.insert(0, module_dir)
        from fraud_detection import assemble_report

        raw = self.fraud_data.data if isinstance(self.fraud_data, Data) else self.fraud_data
        if not isinstance(raw, dict) or raw.get("error"):
            msg = raw.get("error") if isinstance(raw, dict) else "Data Fase 1 tidak valid."
            return Message(text=f"Laporan tidak dapat dibuat: {msg}")

        text = assemble_report(raw, _as_text(self.legal_output), _as_text(self.regulation_context))
        self.status = "Laporan dirakit & divalidasi"
        return Message(text=text)
